class MeasurementPointItem(BaseModel):
    model_config = ConfigDict(
        extra="forbid",
    )
    name: Annotated[str, Field(title="Name")]
    """
    The name the measurement point is commonly referred to. This is the name that is used to refer to the data in an analysis and reporting.
    """
    measurement_type_id: MeasurementType
    height_m: Annotated[float | None, Field(title="Height [m]")]
    """
    The height (in meters) typically above ground level that the measurement is taking place. If you do not yet know the height please use null.
    """
    height_reference_id: Annotated[HeightReference | None, Field(title="Height Reference")] = (
        HeightReference.ground_level
    )
    """
    The height reference frame that is used to measure the item height. E.g. onshore this is 'ground level' i.e. the item is 0.5 m above ground level. Offshore is a bit different as it can be 20 m above 'mean sea level' or 20 m above 'lowest astronomical tide' for a fixed structure or 20 m above 'sea level' for a floating lidar.
    """
    notes: Annotated[str | None, Field(examples=["I can write anything I want here."], title="Notes")] = None
    """
    Notes relating to these properties.
    """
    update_at: Annotated[datetime | None, Field(examples=["2020-07-28T20:49:13"], title="Date of Update")] = None
    """
    The date these properties were last updated.
    """
    logger_measurement_config: Annotated[
        UniqueList[LoggerMeasurementConfigItem],
        Field(title="Logger Measurement Configuration"),
    ]
    """
    The measurement configuration that is programmed into the logging device.
    """
    sensor: Annotated[UniqueList[SensorItem] | None, Field(title="Sensor")] = None
    """
    This represents information about the sensor taking the measurements.
    """
    mounting_arrangement: Annotated[UniqueList[MountingArrangementItem] | None, Field(title="Mounting Arrangement")] = (
        None
    )
    """
    This describes how the sensor is mounted onto the met mast.
    """
    interference_structures: Annotated[
        UniqueList[InterferenceStructure] | None, Field(title="Interference Structures")
    ] = None


class MeasurementLocationItem(BaseModel):
    model_config = ConfigDict(
        extra="forbid",
    )
    uuid: Annotated[
        UUID | None,
        Field(examples=["3d40f012-a525-4024-a626-5fcf954c59cf"], title="UUID"),
    ] = None
    """
    The unique identifier of the measurement location in the UUID format. A UUID can be generated here https://www.uuidgenerator.net/
    """
    name: Annotated[str, Field(examples=["AName_MM1"], title="Name")]
    """
    The name given to the measurement location i.e. to the met mast or remote sensing device. Unique names are recommended to avoid two locations in the same context being given the same name.
    """
    latitude_ddeg: Annotated[float, Field(examples=[52.973], ge=-90.0, le=90.0, title="Latitude [ddeg]")]
    """
    Latitude coordinate in the Geographic Coordinate System using the WGS84 reference coordinate system, [EPSG:4326](https://epsg.io/4326). Unit of measure is in decimal degrees. Latitude lines are parallel to the equator where their position ranges from -90 degrees at the south pole to 90 degrees at the north pole.
    """
    longitude_ddeg: Annotated[float, Field(examples=[-9.431], ge=-180.0, le=180.0, title="Longitude [ddeg]")]
    """
    Longitude coordinate in the Geographic Coordinate System using the WGS84 reference coordinate system, [EPSG:4326](https://epsg.io/4326). Unit of measure is in decimal degrees. Longitude lines are perpendicular to the equator where their position ranges from 0° at Greenwich Mean Time increasing to +180° as you move eastward and decreasing to −180° as you move westward.
    """
    measurement_station_type_id: Annotated[MeasurementStationTypeId, Field(title="Measurement Station Type")]
    """
    The type of measurement station. This must be one of either met mast, lidar (a vertical profiler), sodar (also a vertical profiler), floating lidar (floating vertical profiler lidar), wave buoy, ADCP (Acoustic Doppler Current Profiler) or a solar measurement station.
    """
    notes: Annotated[str | None, Field(examples=["I can write anything I want here."], title="Notes")] = None
    """
    Notes relating to these properties.
    """
    update_at: Annotated[datetime | None, Field(examples=["2020-07-28T20:49:13"], title="Date of Update")] = None
    """
    The date these properties were last updated.
    """
    mast_properties: Annotated[MastProperties | None, Field(title="Mast Properties")] = None
    """
    The properties of the installed met mast/tower. Additional properties can be added e.g. 'material' however this wouldn't be part of the Data Model. If an additional property is for information purposes please consider using 'notes' instead.
    """
    vertical_profiler_properties: Annotated[
        UniqueList[VerticalProfilerProperty] | None,
        Field(title="Vertical Profiler Properties"),
    ] = None
    """
    Vertical profiler remote sensing devices (e.g. lidar, sodar and floating lidar) installation specific properties.
    """
    logger_main_config: Annotated[UniqueList[LoggerMainConfigItem] | None, Field(title="Logger Configuration")] = None
    """
    This represents how the logger's main settings are configured. For example, it's sampling rate or averaging period. For remote sensing devices, such as lidar's, the device itself is considered as a logger and so these logger configuration attributes should be used to describe the lidar.
    """
    model_config_: Annotated[
        UniqueList[ModelConfigItem] | None,
        Field(alias="model_config", title="Model Configuration"),
    ] = None
    """
    This represents how a simulation model or other model that produces a synthetic timeseries dataset is configured. This also includes reanalysis datasets.
    """
    measurement_point: Annotated[UniqueList[MeasurementPointItem], Field(title="Measurement Point")]
    """
    This represents a point in space where a measurement takes place.
    """


class IeaWindResourceAssessmentDataModel(BaseModel):
    """
    This Data Model schema is a digital representation of a meteorological mast used for measuring the wind resource of a potential wind farm.
    """

    model_config = ConfigDict(
        extra="allow",
    )
    author: Annotated[str, Field(examples=["Stephen Holleran", "Joe Bloggs"], title="Author")]
    """
    The person or system who created this data model representing a specific mast.
    """
    organisation: Annotated[str, Field(examples=["brightwind", "Wind Developer Ltd."], title="Organisation")]
    """
    The organisation the Author is from.
    """
    date: Annotated[date_aliased, Field(examples=["2020-07-28"], title="Date")]
    """
    The date this file was created. Format should be YYYY-MM-DD
    """
    version: Annotated[
        str,
        Field(
            examples=["0.1.0-2020.06", "1.1.1-2020.07"],
            pattern="^([0-9]{1,2})[.]([0-9]{1,2})[.]([0-9]{1,2})-([0-9]{4})[.]([0-9]{2})$",
            title="Version",
        ),
    ]
    """
    The version of the IEA WRA Data Model this file is based on. The format of this follows Semantic Versioning with the year and month tagged on after. E.g. 1.1.1-2020.07
    """
    license: Annotated[
        str | None,
        Field(
            examples=["https://opensource.org/license/bsd-3-clause/", "BSD-3-Clause"],
            title="License",
        ),
    ] = None
    """
    Expected to be used as the Dublin Core Metadata Initiative intended. Link: http://purl.org/dc/terms/license Definition: A legal document giving official permission to do something with the resource. Comment: Recommended practice is to identify the license document with a URI. If this is not possible or feasible, a literal value that identifies the license may be provided.
    """
    plant_name: Annotated[str | None, Field(examples=["A Name of Wind Farm"], title="Plant Name")] = None
    """
    The name of the wind farm this met mast is associated with.
    """
    plant_type: Annotated[PlantType | None, Field(title="Plant Type")] = None
    """
    The type of renewable generation plant it is.
    """
    measurement_location: Annotated[UniqueList[MeasurementLocationItem], Field(title="Measurement Location")]
    """
    This is the geographic location of the meteorological measurement station i.e. a met mast/tower or remote sensing device.
    """
